let file = """{"version":3,"file":"nodeDefStore-B8cjfdeD.js","names":[],"sources":["../../src/lib/litegraph/src/ContextMenu.ts","../../src/lib/litegraph/src/measure.ts","../../src/lib/litegraph/src/CurveEditor.ts","../../src/renderer/core/canvas/canvasViewport.ts","../../src/lib/litegraph/src/DragAndScale.ts","../../src/schemas/subgraphIdSchema.ts","../../src/types/widgetId.ts","../../src/types/widgetVisibility.ts","../../src/lib/litegraph/src/graphIntents.ts","../../src/stores/widgetValueStore.ts","../../src/core/graph/subgraph/adoptPromotedWidgetValue.ts","../../src/core/selection/selectionState.ts","../../src/stores/linkPresentationStore.ts","../../src/core/graph/transferLinkPresentation.ts","../../src/lib/litegraph/src/constants.ts","../../src/lib/litegraph/src/utils/type.ts","../../src/lib/litegraph/src/litegraphInstance.ts","../../src/lib/litegraph/src/utils/textMeasureCache.ts","../../src/lib/litegraph/src/draw.ts","../../src/lib/litegraph/src/infrastructure/Rectangle.ts","../../src/lib/litegraph/src/widgets/BaseWidget.ts","../../src/lib/litegraph/src/widgets/AssetWidget.ts","../../src/lib/litegraph/src/widgets/BooleanWidget.ts","../../src/lib/litegraph/src/widgets/BoundingBoxWidget.ts","../../src/lib/litegraph/src/widgets/ButtonWidget.ts","../../src/lib/litegraph/src/widgets/VueOnlyWidget.ts","../../src/lib/litegraph/src/widgets/ChartWidget.ts","../../src/lib/litegraph/src/widgets/ColorWidget.ts","../../src/lib/litegraph/src/utils/feedback.ts","../../src/lib/litegraph/src/widgets/BaseSteppedWidget.ts","../../src/lib/litegraph/src/widgets/ComboWidget.ts","../../src/lib/litegraph/src/widgets/CurveWidget.ts","../../src/lib/litegraph/src/widgets/FileUploadWidget.ts","../../src/lib/litegraph/src/widgets/GalleriaWidget.ts","../../src/lib/litegraph/src/widgets/GradientSliderWidget.ts","../../src/lib/litegraph/src/widgets/ImageCompareWidget.ts","../../src/lib/litegraph/src/widgets/BoundingBoxesWidget.ts","../../src/lib/litegraph/src/widgets/LightInfoWidget.ts","../.